import { nanoid } from "nanoid"

export const collectUsers = (data)=>{
return{
    id : nanoid(6),
    name : data.name.value,
    surname : data.sName.value,
    age: data.age.value,
    file: URL.createObjectURL(data.file.files[0]) 
}
}
